/* Athanor — translations. Keys are the English source strings; a missing key falls back to English.
   {0}, {1}… are substituted with arguments. */
"use strict";

// Palette and accent are applied before anything renders (remembered per browser), then confirmed by the server.
try { const th = localStorage.getItem("theme"), ac = localStorage.getItem("accent"); if (th) document.documentElement.dataset.theme = th; if (ac) document.documentElement.dataset.accent = ac; } catch (e) { /* storage unavailable */ }
function appliquerTheme(theme, accent) {
  const r = document.documentElement;
  if (theme) r.dataset.theme = theme; else delete r.dataset.theme;
  if (accent) r.dataset.accent = accent; else delete r.dataset.accent;
  try { localStorage.setItem("theme", theme || ""); localStorage.setItem("accent", accent || ""); } catch (e) { /* ignore */ }
}
