let dictionnaireCourant = {};
function appliquerLangue(code) { dictionnaireCourant = DICT[code] || {}; document.documentElement.lang = code; }
function t(cle, args) {
  // "[M4] …" : a worker's line (parallel mode); the tag is kept and the rest translated
  const m = typeof cle === "string" && /^\[[^\]]+\] /.exec(cle);
  if (m) return m[0] + t(cle.slice(m[0].length), args);
  let s = dictionnaireCourant[cle];
  if (s === undefined) {
    // journal and task prefixes: translate the known beginning, keep the dynamic rest
    for (const p of PREFIXES) { if (cle.startsWith(p)) { const tp = dictionnaireCourant[p]; s = (tp === undefined ? p : tp) + cle.slice(p.length); break; } }
    if (s === undefined) s = cle;
  }
  if (args) args.forEach((a, i) => { s = s.split("{" + i + "}").join(String(a)); });
  return s;
}
